from umllib import *
import sys
H = int(sys.argv[1]) if len(sys.argv) > 1 else 1800
b = Board('UML_Rules', 'Rules', 1280, H, hdr=False)
css = '''<style>.rc{background:#fff;border:1px solid #E2E8F0;border-radius:14px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;box-sizing:border-box}.rc h2{font-size:16px;font-weight:800}.rc li{font-size:13px;line-height:20px;color:#334155;margin-bottom:6px}.rc ul{padding-left:18px;margin:0}.mono{font-family:'JetBrains Mono',monospace;font-size:12px}</style>'''
def card(t, inner): return f'<div class="rc"><h2>{t}</h2>{inner}</div>'
def ul(*it): return '<ul>' + ''.join(f'<li>{i}</li>' for i in it) + '</ul>'
cards = [
 card('What it covers', ul('Three UML types on this page: <b>state machine</b> (how one thing changes over time), <b>use case</b> (who uses a system, and for what), <b>class diagram</b> (the parts of a program and how they relate).', 'Sequence has its own page. An <b>activity</b> diagram is drawn as a flowchart with fork and join bars.', 'The same palette, icons and tints as the other types. Blue animated line: the happy path.')),
 card('State machine: states', ul('A state is a rounded box, 160 × 64, tinted by phase. Its name is a noun or an adjective: <i>Paid</i>, <i>On the way</i>.', 'An activity that runs while in the state is mono, grey, under the name: <span class="mono">do / cook</span>. Also <span class="mono">entry /</span> and <span class="mono">exit /</span>.', 'A <b>frame</b> with a pill label groups states into one composite state (<i>Delivering</i>).', 'Start: a filled dot. End: a ringed dot. More than one end is allowed.')),
 card('State machine: transitions', ul('A label has up to three parts: <span class="mono">event [guard] / action</span>. Any part may be left out.', 'Event: what happens, in words. Guard: a condition in brackets. Action: what runs on the way.', 'Failure and cancel paths are rose. The happy path is blue, thick and animated: one per diagram.', 'A transition from a state to itself is a loop above the box.', 'Leave 130 px between states that carry a label.')),
 card('Use case: parts', ul('<b>Actor:</b> a person or an external system, outside the frame. Plain: a stick figure. Illustrated: a card with a large icon. An external system is marked <i>external system</i>.', '<b>System frame:</b> a white rectangle with the system name at the top left.', '<b>Use case:</b> an ellipse 240 × 64, a verb phrase, tinted by who mainly uses it.')),
 card('Use case: lines', ul('A solid line without arrowhead: the actor takes part.', 'A dashed arrow with an open head: <span class="mono">«include»</span> (always used) or <span class="mono">«extend»</span> (sometimes added). The arrow points at the use case that is included or extended.', 'Actors sit left, external systems right. Keep use cases of one actor in one column.')),
 card('Class: boxes', ul('Three compartments: name, attributes, operations. Width 280 px. The header carries the class tint.', 'An abstract class is italic. An interface gets <span class="mono">«interface»</span> above its name.', 'Visibility: <span class="mono">+</span> public, <span class="mono">-</span> private, <span class="mono">#</span> protected. Type after a colon.', 'An empty compartment is left out: an interface has no attribute box. Show the members that explain the relationships, not every field.')),
 card('Class: relationships', ul('<b>Association:</b> plain line with names and multiplicity. <b>Navigable:</b> open arrow.', '<b>Composition:</b> filled diamond at the whole. <b>Aggregation:</b> hollow diamond.', '<b>Inheritance:</b> hollow triangle at the parent. <b>Realises an interface:</b> the same triangle on a dashed line.', '<b>Dependency:</b> dashed line with an open arrow.', 'Multiplicity next to the end: <span class="mono">1</span>, <span class="mono">0..1</span>, <span class="mono">0..*</span>, <span class="mono">1..*</span>.')),
 card('Layout and spacing', ul('Parents above or left of children. The class the story is about sits top left.', 'Classes in a grid, 460 px apart sideways and 340 px apart downward. A label needs 90 px of line.', 'About ten classes per page. More: one diagram per module.', 'Routes are orthogonal with at most two bends. A line never crosses a box.')),
 card('Plain and illustrated', ul('<b>Use case</b> has both: stick figures, or icon cards for actors.', '<b>State machine and class diagram</b> are plain only. Their meaning is in the shapes and the labels, and large icons would crowd them.', 'Rules stay the same in both styles.')),
 card('Animation', ul('Only the happy path of a state machine animates: blue, thick, fast. One per diagram.', 'Use case and class diagrams do not animate.', 'Off when the viewer prefers reduced motion. In draw.io each line has its own flow animation (flowAnimation=1) and its own duration: main route 500, event stream 1500. Checked in the draw.io viewer; SVG export not yet tested.')),
 card('Reading it with other types', ul('A state machine often belongs to one table in an ER diagram: the status column. A use case is often one sequence diagram. Keep names the same.', 'A class diagram of the domain and an ER diagram of the tables describe the same things; classes are singular and PascalCase, tables are singular too.', 'Not decided yet: links between a use case and its sequence page.')),
 card('What a plugin can rely on', ul('State machine: states (name, tone, activities, parent), transitions (from, to, event, guard, action, kind), initial and final markers.', 'Use case: actors (name, icon, external), use cases (name, actor), relations (actor-usecase, include, extend).', 'Class diagram: classes (name, kind, abstract, attributes, operations), relations (from, to, kind, multiplicity at each end, label).', 'Layout comes from a grid; the plugin routes the lines.', 'Anything not covered is left to the diagram author.')),
]
grid = f'<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px">{"".join(cards)}</div>'
b.raw(css + f'<div style="position:absolute;left:0;top:0;width:1280px;box-sizing:border-box;padding:64px;display:flex;flex-direction:column;gap:28px"><div style="display:flex;flex-direction:column;gap:8px"><div style="font-size:24px;font-weight:600">UML · Rules</div><div style="font-size:13px;line-height:20px;color:#475569;max-width:900px">State machine, use case and class diagram: the conventions and what a plugin can rely on. The examples follow the same food-delivery story as the other types.</div></div>{grid}</div>')
print(save5(b))
